function UICultivateEquipBaseBackpackNodeMB:InitListener()
    self.eventConf = {
        [Constants.EventNames.UICultivateEquipSuitFilterEntry] = Bind(self, self.OnEntryEquipSuitFilterListener),
        [Constants.EventNames.UICultivateEquipSuitFilterComplete] = Bind(self, self.OnSuitFilterSelectCompleteListener),
        --[Constants.EventNames.UICultivateEquipSuitFilterClose] = Bind(self, self.OnCloseFilterListener),
        [Constants.EventNames.UICultivateEquipChangeLockStateComplete] = Bind(self, self.OnChangeLockState),
    }
    for key, func in pairs(self.eventConf) do
        Events.AddListener(key, func)
    end

    self.__toggleAction = function(selectType, isOn)
        if self.selectType == selectType then return end
        self:SwitchSelectType(selectType)
        local part = SelectType2Part[selectType]
        self:RefreshScrollViewByPart(part)

        if self.updatePartAction then
            self.updatePartAction(part)
        end

        self.selectType = selectType
    end
    self.TabGroup.OnTabChangeEvent:AddListener(self.__toggleAction)
end

function UICultivateEquipBaseBackpackNodeMB:RemoveAllListener()
    for key, func in pairs(self.eventConf) do
        Events.RemoveListener(key, func)
    end
    self.eventConf = nil

    self.TabGroup.OnTabChangeEvent:RemoveListener(self.__toggleAction)
end

function UICultivateEquipBaseBackpackNodeMB:InitCoreData(t, filterCallback)
    ---@type EquipmentComponent
    local equipComp = self.equipComp
    local equipmentCoreDojos = equipComp:GetAllEquipCores()
    local temp = self.coreRefId2ConfigInfo
    local occupationId, quality, suitId = 0, 0, 0
    ---@param v EquipmentCoreDojo
    for i, v in ipairs(equipmentCoreDojos) do
        local refId = v.equipmentCoreId
        if temp[tostring(refId)] == nil then
            ---@type EquipCoreVo
            local equipCoreVo = cardConfMgr:GetEquipCoreVoById(refId)
            --
            occupationId, quality, suitId = equipCoreVo.occupationId, equipCoreVo.quality, equipCoreVo.suitId
            temp[tostring(refId)] = { occupationId, quality, suitId}
        else
            occupationId, quality, suitId = SafeUnpack(temp[tostring(refId)])
        end
        if filterCallback(v) then
            table.insert(t, self:CreateEquipCoreData(v, refId, occupationId, quality, suitId))
        end
    end

    self.coreRefId2ConfigInfo = temp
end

---CreateEquipCoreData
---@param equipmentCoreDojo EquipmentCoreDojo
---@param equipmentCoreId number 装备核心配表id
---@param occupationId number 装备核心职业限制
---@param quality Constants.QualityType
function UICultivateEquipBaseBackpackNodeMB:CreateEquipCoreData(equipmentCoreDojo, equipmentCoreId, occupationId, quality, suitId)
    return EquipUtils.GenerateEquipCoreData(equipmentCoreDojo, equipmentCoreId, occupationId, quality, suitId)
end

---InitEquipData
---初始化装备数据
---@param t table
function UICultivateEquipBaseBackpackNodeMB:InitEquipData(t, filterCallback)
    local temp = self.equipRefId2ConfigInfo
    ---@type EquipmentComponent
    local equipComp = self.equipComp
    ---@type EquipDojo[]
    local equipDojos = equipComp:GetAllEquips()
    local quality, part, suitId = 0, 0, 0
    ---@param v EquipDojo
    for i, v in ipairs(equipDojos) do
        local equipmentId = v.equipmentId

        if temp[tostring(equipmentId)] == nil then
            ---@type EquipVo
            local equipVo = cardConfMgr:GetEquipVoById(equipmentId)
            quality, part, suitId = equipVo.rare, equipVo.part, equipVo.suitId
            temp[tostring(equipmentId)] = {quality, part, suitId}
        else
            quality, part, suitId = SafeUnpack(temp[tostring(equipmentId)])
        end
        if filterCallback(v, part)then
            table.insert(t, self:CreateEquipData(v, equipmentId, quality, part, suitId))
        end
    end
end

function UICultivateEquipBaseBackpackNodeMB:CreateEquipData(equipDojo, equipmentId, quality, part, suitId)
    return EquipUtils.GenerateEquipData(equipDojo, equipmentId, quality, part, suitId)
end

---InitSuitEquipPartData
---初始化套装 装备 位置数据
---@param t table 套装位置数据列表
---@param ownEquipPartMap table<number, table> table<装备的位置, 在该位置上拥有的装备列表>
---@param filterCallback fun(equipDojo:EquipDojo, equipVo:EquipVo):boolean 过滤回调
function UICultivateEquipBaseBackpackNodeMB:InitSuitEquipPartData(t, ownEquipPartMap, filterCallback)
    local equipComp = self.equipComp
    for part = 1, Constants.CardEquipmentNo do
        t[part] = t[part] or {}
        local playerEquipIds = ownEquipPartMap[part] or {}
        for i, playerEquipId in ipairs(playerEquipIds) do
            ---@type EquipDojo
            local equipDojo = equipComp:GetEquipById(playerEquipId)
            local refId = equipDojo.equipmentId
            local equipVo = cardConfMgr:GetEquipVoById(refId)
            ---再该套装中
            if filterCallback(equipDojo, equipVo) then
                table.insert(t[part], self:CreateEquipData(equipDojo, refId, equipVo.rare, part, equipVo.suitId))
            end
        end
    end
end

---InitSuitEquipCorePartData
---初始化套装 装备核心 位置数据
---@param t table 套装位置数据列表
---@param ownEquipPartMap table<number, table> table<装备的位置, 在该位置上拥有的装备列表>
---@param filterCallback fun(equipmentCoreDojo:EquipmentCoreDojo, equipCoreVo:EquipCoreVo):boolean 过滤回调
function UICultivateEquipBaseBackpackNodeMB:InitSuitEquipCorePartData(t, ownEquipPartMap, filterCallback)

    local equipComp = self.equipComp

    local part = -1
    t[part] = t[part] or {}
    local playerEquipCoreIds = ownEquipPartMap[part] or {}
    for i, coreId in ipairs(playerEquipCoreIds) do
        ---@type EquipmentCoreDojo
        local equipmentCoreDojo = equipComp:GetEquipCoreById(coreId)
        local refId = equipmentCoreDojo.equipmentCoreId
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(refId)
        ---再该套装中
        if filterCallback(equipmentCoreDojo, equipCoreVo) then
            table.insert(t[part], self:CreateEquipCoreData(equipmentCoreDojo, refId, equipCoreVo.occupationId, equipCoreVo.quality, equipCoreVo.suitId))
        end
    end
end

function UICultivateEquipBaseBackpackNodeMB:AddSuitDataPartListByEquipIdList(equipIdList)
    if self:GetFilterType() ~= FilTerType.SUIT then return end

    for i, equipId in ipairs(equipIdList) do
        if checkNumber(equipId) > 0 then
            self:AddSuitDataPartListByEquipId(equipId)
        end
    end
end

function UICultivateEquipBaseBackpackNodeMB:AddSuitDataPartListData(id, part)
    if part == -1 then
        self:AddSuitDataPartListByCoreId(id)
    elseif part > 0 then
        self:AddSuitDataPartListByEquipId(id)
    end
end

---AddSuitDataPartListByEquipId
---根据 装备数据库id 添加套装位置数据
---@param playerEquipId number 装备数据库id
function UICultivateEquipBaseBackpackNodeMB:AddSuitDataPartListByEquipId(playerEquipId)
    local temp = checkNumber(playerEquipId)
    local equipIdList = self:GetEquipIdList()
    for i, v in pairs(equipIdList) do
        if checkNumber(v) == temp then
            return
        end
    end

    ---@type EquipDojo
    local equipDojo = self.equipComp:GetEquipById(playerEquipId)
    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local suitId = checkInt(equipVo.suitId)
    if suitId == self.curSelectSuitId and self.curSelectSuitId > 0 then
        local part = checkNumber(equipVo.part)
        local suitDataPartList = self.suitDataPartList
        suitDataPartList[part] = suitDataPartList[part] or {}

        if self:CheckIsCanInsert(suitDataPartList[part], checkNumber(playerEquipId), equipDojo, equipVo, true) then
            table.insert(suitDataPartList[part], self:CreateEquipData(equipDojo, equipDojo.equipmentId, equipVo.rare, part, suitId))
        end
    end
end

---AddSuitDataPartListByCoreId
---根据 装备核心数据库id 添加套装位置数据
---@param coreId number 装备核心数据库id
function UICultivateEquipBaseBackpackNodeMB:AddSuitDataPartListByCoreId(coreId)
    if checkNumber(coreId) <= 0 or checkNumber(self:GetPlayerEquipCoreId()) == coreId then return end

    ---@type EquipmentCoreDojo
    local equipmentCoreDojo = self.equipComp:GetEquipCoreById(coreId)
    local refId = equipmentCoreDojo.equipmentCoreId
    ---@type EquipCoreVo
    local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreDojo.equipmentCoreId)
    local suitId = checkInt(equipCoreVo.suitId)
    if suitId == self.curSelectSuitId and self.curSelectSuitId > 0 then
        local part = -1
        local suitDataPartList = self.suitDataPartList
        suitDataPartList[part] = suitDataPartList[part] or {}
        if self:CheckIsCanInsert(suitDataPartList[part], checkNumber(coreId), equipmentCoreDojo, equipCoreVo) then
            table.insert(suitDataPartList[part], self:CreateEquipCoreData(equipmentCoreDojo, refId, equipCoreVo.occupationId, equipCoreVo.quality, equipCoreVo.suitId))
        end
    end
end

---RemoveSuitDataPartListData
---移除套装位置列表数据
---@param id number 数据id
---@param part number 套装散件位置
function UICultivateEquipBaseBackpackNodeMB:RemoveSuitDataPartListData(id, part)
    local suitDataPartList = self.suitDataPartList
    suitDataPartList[part] = suitDataPartList[part] or {}
    id = checkNumber(id)
    local partData = suitDataPartList[part]
    for i, suitDataPartData in ipairs(partData) do
        local dataId = checkNumber(suitDataPartData.id)
        if dataId == id then
            table.remove(suitDataPartList[part], i)
            break
        end
    end
end

---UpdateSuitDataPartList
---@param newId number 背包中新增id
---@param oldId number 背包中要移除的id
---@param part number -1 核心, > 0 装备
function UICultivateEquipBaseBackpackNodeMB:UpdateSuitDataPartList(newId, oldId, part)
    if newId > 0 then
        self:AddSuitDataPartListData(newId, part)
    end
    if oldId > 0 then
        self:RemoveSuitDataPartListData(oldId, part)
    end
end

function UICultivateEquipBaseBackpackNodeMB:CheckIsCanInsert(partList, id, dojo, vo)
    local isCanInsert = true
    for i, v in ipairs(partList) do
        if checkNumber(v.id) == id then
            isCanInsert = false
            break
        end
    end
    if isCanInsert then
        isCanInsert = EquipUtils.CheckEquipFilterCondition({
            mainAttrId = dojo.mainAttrId,
            occupationId = checkNumber(vo.occupationId),
            playerCardId = dojo.playerCardId,
            quality = vo.quality or vo.rare
        }, self:GetGroups(), {career = self:GetCardCareerId()})
    end
    return isCanInsert
end

