---RefreshScrollView
---@param result table
function UICultivateEquipBaseBackpackNodeMB:RefreshScrollView(result)
    local count = #result
    local isShowList = count > 0
    KTool.SetActive(self.EmptyEquipTipNode.gameObject, not isShowList)
    KTool.SetActive(self.ScrollRoot.gameObject, isShowList)
    if isShowList then
        -- local ScrollView = self.ScrollView.mLoopListView
        -- if not ScrollView.IsListViewInit then
        --     self.ScrollView:InitListView(count, Bind(self, self.OnGetItemByIndex))
        -- else
        --     GameUtils.ReloadData(self.ScrollView, count)
        -- end
        local List = self.ScrollView
        if not List.mLoopListView.IsListViewInit then
            List:InitListView(count, Bind(self, self.OnGetItemByIndex))
        else
            GameUtils.ReloadData(List, count)
            List:MovePanelToItemIndex(0)
        end
    else
        local part = self:GetPart()
        local config = {
            [-1] = localize("暂无情绪涂鸦核心"),
        }
        if self:GetFilterType() == FilTerType.SUIT then
            config[0] = localize("暂无该套装的情绪涂鸦")
        end

        local text = config[part]
        text = text ~= nil and text or localize("暂无情绪涂鸦")

        ---@type EmptyNodeMB
        local env = CfUtils.GetLuaScr(self.EmptyEquipTipNode.gameObject, EmptyNodeMBPath)
        if not isNull(env) then
            env:SetText(text)
        end
    end
    return isShowList
end

---OnGetItemByIndex
---@param idx number
function UICultivateEquipBaseBackpackNodeMB:OnGetItemByIndex(cell, idx)
    if idx < 0 then return nil end

    ---@type UICultivateEquipBackpackCellNode
    local nodeEnv = CfUtils.GetLuaScr(cell, GoodNodePrefabPath)
    if isNull(nodeEnv) then
        return nil
    end

    if nodeEnv.clickAction == nil then
        nodeEnv:SetClickCallback(Bind(self, self.OnClickCellAction))
        ---子类 方法
        if self.OnLongTapCellAction then
            nodeEnv:SetLongTapCallback(Bind(self, self.OnLongTapCellAction))
        end
        --
        --local Container = cellTrans:Find("GoodNode")
        --local group = KTool.GetOrAddComponent(Container.gameObject, CanvasGroupType)
        --group.alpha = 0
        --group:DOFade(1, 0.3):SetDelay(0.02 * idx)
    end

    local index     = idx + 1
    local cellTrans = cell.transform
    cellTrans.gameObject:EnsureComponent(IDType).id = index

    --- 调用子类
    self:RefreshGoodsNode(nodeEnv, index)

    return cell
end

