function UICultivateEquipBaseBackpackNodeMB:GetAllSuitDataPartListData()
    local suitDataPartList = self.suitDataPartList
    local multipleSuitDataPartList = {}
    for i, v in pairs(suitDataPartList) do
        for _, vv in ipairs(v) do
            table.insert(multipleSuitDataPartList, vv)
        end
    end
    return multipleSuitDataPartList
end

function UICultivateEquipBaseBackpackNodeMB:GetSuitDataPartListData()
    return self.suitDataPartList[self.part]
end

function UICultivateEquipBaseBackpackNodeMB:GetGroups()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.FilterNode.gameObject, FilterNodePath)
    if isNull(nodeEnv) then return end
    return nodeEnv:GetGroups()
end

function UICultivateEquipBaseBackpackNodeMB:SetStoreKey(storeKey)
    self.storeKey = storeKey
end
function UICultivateEquipBaseBackpackNodeMB:GetStoreKey()
    return self.storeKey
end


