function UICultivateEquipBaseBackpackNodeMB:OnChangeLockState(curId, locked)
    curId = checkNumber(curId)
    local backpackList = self:GetBackpackDataList()
    for i, v in ipairs(backpackList) do
        if checkNumber(v.id) == curId then
            v.locked = locked
            local isShowLock = locked > 0
            self:RefreshCellLockedShowStateByIndex(i, isShowLock)
            break
        end
    end
end

